<?php require __DIR__.'/app.php';if(PHP_SAPI!=='cli'){http_response_code(404);exit;}if($argc!==4){fwrite(STDERR,"Usage: php create_admin.php shop-name email password-12-chars\n");exit(2);}[$scriptPath,$shopName,$ownerEmail,$ownerPassword]=$argv;if(!filter_var($ownerEmail,FILTER_VALIDATE_EMAIL)||strlen($ownerPassword)<12){fwrite(STDERR,"Invalid email or password too short.\n");exit(2);}$database=db();if((int)$database->query('SELECT COUNT(*) FROM users')->fetchColumn()){fwrite(STDERR,"Account already exists.\n");exit(1);}$database->beginTransaction();try{$statement=$database->prepare('INSERT INTO shops(name) VALUES(?)');$statement->execute([$shopName]);$statement=$database->prepare("INSERT INTO users(shop_id,email,password_hash,role) VALUES(?,?,?,'owner')");$statement->execute([(int)$database->lastInsertId(),strtolower($ownerEmail),password_hash($ownerPassword,PASSWORD_DEFAULT)]);$database->commit();echo "Owner account created.\n";}catch(Throwable $creationException){$database->rollBack();fwrite(STDERR,"Creation failed.\n");exit(1);}
